#include <bits/stdc++.h>
#define reg register
#define int long long
using namespace std;

inline int read_input() {
    int sign=1, val=0; char ch=getchar();
    while (ch<'0'||ch>'9') { if (ch=='-') sign=-1; ch=getchar(); }
    while (ch>='0'&&ch<='9') { val=val*10+ch-48; ch=getchar(); }
    return sign*val;
}

inline int min_of(reg int a, reg int b) { return a<b?a:b; }
inline int max_of(reg int a, reg int b) { return a>b?a:b; }

const int MAX_SIZE=2000010, MOD_A=1000000007, MOD_B=998244353, BASE_NUM=1000000;
int total_count, current_idx, answer_sum, prefix_sum_arr[10];
vector<int> digit_buckets[10];

inline int mod_calc(reg int x) { return (x%MOD_B+MOD_B)%MOD_B; }

void build_sequence(reg int start, reg int depth) {
    ++total_count;
    digit_buckets[depth].push_back(mod_calc(total_count - start));
    (answer_sum += digit_buckets[depth].back()) %= MOD_A;
    if (depth==6) return;
    for (reg int d=0; d<10; d++) build_sequence(start*10+d, depth+1);
}

void traverse_sequence(reg int num) {
    if (num > n) return;
    if (num*BASE_NUM + (BASE_NUM-1) <= n && num*BASE_NUM*10 > n) {
        reg int prev_idx=total_count;
        for (reg int level=0, mult=1; level<=6; level++, mult*=10) {
            reg int size=digit_buckets[level].size();
            reg int delta=mod_calc(prev_idx - num*mult);
            reg int pos=lower_bound(digit_buckets[level].begin(), digit_buckets[level].end(), MOD_B - delta) - digit_buckets[level].begin();
            answer_sum=(answer_sum + delta*size + prefix_sum_arr[level] - MOD_B*(size - pos))%MOD_A;
            total_count+=size;
        }
        return;
    }
    ++total_count;
    answer_sum=(answer_sum + mod_calc(total_count - num))%MOD_A;
    for (reg int d=0; d<10; d++) traverse_sequence(num*10+d);
}

signed main() {
    n=read_input();
    build_sequence(0,0);
    for (reg int i=0; i<=6; i++) sort(digit_buckets[i].begin(), digit_buckets[i].end());
    total_count=0;
    for (reg int i=1; i<=9; i++) traverse_sequence(i);
    printf("%lld", (answer_sum+MOD_A)%MOD_A);
    return 0;
}
